//! Official Envoy wire vectors and hostile ClientStatusRequest boundaries.
const std = @import("std");
const csds = @import("csds.zig");
const allocator = std.testing.allocator;
const current_status_schema = @embedFile("csds_schema/client_resource_status.proto");

// Generated by the pinned official csds.proto ClientStatusResponse encoder.
// GenericXdsConfig.error_state=8; UpdateFailureState timestamp=2/details=3/version=4.
const official_full = "\x0a\x40\x1a\x38\x0a\x01t\x12\x01n\x1a\x08accepted\x22\x07\x0a\x01t\x12\x02ok\x2a\x04\x08\x03\x10\x04\x38\x04\x42\x15\x12\x04\x08\x07\x10\x7b\x1a\x08rejected\x22\x03bad\x22\x04grpc";
const official_excluded = "\x0a\x37\x1a\x2f\x0a\x01t\x12\x01n\x1a\x08accepted\x2a\x04\x08\x03\x10\x04\x38\x04\x42\x15\x12\x04\x08\x07\x10\x7b\x1a\x08rejected\x22\x03bad\x22\x04grpc";
const rejected = [_]csds.Resource{.{
    .type_url = "t",
    .name = "n",
    .version = "accepted",
    .wire = "ok",
    .status = .nacked,
    .last_updated_seconds = 3,
    .last_updated_nanos = 4,
    .error_state = .{ .details = "rejected", .version_info = "bad", .last_update_attempt = .{ .seconds = 7, .nanos = 123 } },
}};

fn encodeRejected(gpa: std.mem.Allocator, excluded: bool) !void {
    const encoded = try csds.encodeResponse(gpa, &rejected, .{ .exclude_resource_contents = excluded });
    defer gpa.free(encoded);
    try std.testing.expectEqualSlices(u8, if (excluded) official_excluded else official_full, encoded);
}

test "CSDS codec matches official failure-state wire while retaining accepted metadata" {
    try encodeRejected(allocator, false);
    try encodeRejected(allocator, true);
    try std.testing.checkAllAllocationFailures(allocator, encodeRejected, .{false});
    try std.testing.checkAllAllocationFailures(allocator, encodeRejected, .{true});
}

test "CSDS codec preserves empty failure and timestamp presence and signed seconds" {
    const Case = struct { failure: csds.UpdateFailureState, wire: []const u8 };
    for ([_]Case{
        .{ .failure = .{}, .wire = "\x0a\x0a\x1a\x08\x0a\x01t\x12\x01n\x42\x00" },
        .{ .failure = .{ .last_update_attempt = .{} }, .wire = "\x0a\x0c\x1a\x0a\x0a\x01t\x12\x01n\x42\x02\x12\x00" },
        .{ .failure = .{ .details = "x", .version_info = "v", .last_update_attempt = .{ .seconds = -1, .nanos = 2 } }, .wire = "\x0a\x1f\x1a\x1d\x0a\x01t\x12\x01n\x42\x15\x12\x0d\x08\xff\xff\xff\xff\xff\xff\xff\xff\xff\x01\x10\x02\x1a\x01x\x22\x01v" },
    }) |case| {
        const encoded = try csds.encodeResponse(allocator, &.{.{ .type_url = "t", .name = "n", .status = .unknown, .error_state = case.failure }}, .{ .client_scope = "" });
        defer allocator.free(encoded);
        try std.testing.expectEqualSlices(u8, case.wire, encoded);
    }
}

test "CSDS codec matches current official Envoy received error and timeout statuses" {
    // Envoy API 6ef568cf4a67362849911d1d2a546fd9f35db2ff, pinned by the
    // active gRPC MODULE.bazel. See csds_schema/provenance.json for hashes.
    try std.testing.expect(std.mem.indexOf(u8, current_status_schema, "RECEIVED_ERROR = 5;") != null);
    try std.testing.expect(std.mem.indexOf(u8, current_status_schema, "TIMEOUT = 6;") != null);
    const Case = struct { status: csds.ClientStatus, number: u32, wire: []const u8 };
    // All vectors were generated with the matching current official CSDS and
    // config_dump_shared schemas, preserving the existing values 0 through 4.
    for ([_]Case{
        .{ .status = .unknown, .number = 0, .wire = "\x0a\x08\x1a\x06\x0a\x01t\x12\x01n" },
        .{ .status = .requested, .number = 1, .wire = "\x0a\x0a\x1a\x08\x0a\x01t\x12\x01n\x38\x01" },
        .{ .status = .does_not_exist, .number = 2, .wire = "\x0a\x0a\x1a\x08\x0a\x01t\x12\x01n\x38\x02" },
        .{ .status = .acked, .number = 3, .wire = "\x0a\x0a\x1a\x08\x0a\x01t\x12\x01n\x38\x03" },
        .{ .status = .nacked, .number = 4, .wire = "\x0a\x0a\x1a\x08\x0a\x01t\x12\x01n\x38\x04" },
        .{ .status = .received_error, .number = 5, .wire = "\x0a\x0a\x1a\x08\x0a\x01t\x12\x01n\x38\x05" },
        .{ .status = .timeout, .number = 6, .wire = "\x0a\x0a\x1a\x08\x0a\x01t\x12\x01n\x38\x06" },
    }) |case| {
        try std.testing.expectEqual(case.number, @intFromEnum(case.status));
        const encoded = try csds.encodeResponse(allocator, &.{.{ .type_url = "t", .name = "n", .status = case.status }}, .{ .client_scope = "" });
        defer allocator.free(encoded);
        try std.testing.expectEqualSlices(u8, case.wire, encoded);
    }
}

test "CSDS codec request accepts unknown fields groups and protobuf last-value booleans" {
    // Known messages use length-delimited values; their contents are ignored.
    try std.testing.expect((try csds.decodeRequest("\x0a\x02\x08\x01\x12\x00\x18\x01")).exclude_resource_contents);
    // Unknown fixed64, bytes, fixed32, and a balanced group containing a
    // field-3 value cannot replace the top-level final field-3 value.
    const unknown = "\x21\x01\x02\x03\x04\x05\x06\x07\x08\x2a\x03abc\x35\x01\x02\x03\x04\x3b\x18\x00\x40\x01\x3c";
    const last_true = "\x18\x00" ++ unknown ++ "\x18\x02";
    try std.testing.expect((try csds.decodeRequest(last_true)).exclude_resource_contents);
    try std.testing.expect(!(try csds.decodeRequest("\x18\x01" ++ unknown ++ "\x18\x00")).exclude_resource_contents);
    // Nonminimal valid tags and booleans remain valid protobuf encodings.
    try std.testing.expect((try csds.decodeRequest("\x98\x00\x81\x00")).exclude_resource_contents);
    // Largest allowed unknown field number and largest uint64 value.
    try std.testing.expect((try csds.decodeRequest("\xf8\xff\xff\xff\x0f\xff\xff\xff\xff\xff\xff\xff\xff\xff\x01\x18\x01")).exclude_resource_contents);
    try std.testing.expect((try csds.decodeRequest("\x18\xff\xff\xff\xff\xff\xff\xff\xff\xff\x01")).exclude_resource_contents);
}

test "CSDS codec request rejects oversized tags overflowing varints and wrong known wire types" {
    for ([_][]const u8{
        "\x00", // Field zero.
        "\x80", // Truncated tag.
        "\x80\x80\x80\x80\x10", // Field exceeds protobuf's 29-bit maximum.
        "\x80\x80\x80\x80\x80\x01", // Field exceeds u32 and previously trapped.
        "\xff\xff\xff\xff\xff\xff\xff\xff\xff\x01", // Uint64 tag cannot become a field number.
        "\xff\xff\xff\xff\xff\xff\xff\xff\xff\x02", // Tenth-byte tag overflow.
        "\x80\x80\x80\x80\x80\x80\x80\x80\x80\x80\x00", // Overlong tag.
        "\x18\xff\xff\xff\xff\xff\xff\xff\xff\xff\x02", // Known boolean overflow.
        "\x20\xff\xff\xff\xff\xff\xff\xff\xff\xff\x02", // Unknown value overflow.
        "\x0a\xff\xff\xff\xff\xff\xff\xff\xff\xff\x02", // Length overflow.
        "\x0a\x01", // Truncated known message.
        "\x22\xff\xff\xff\xff\xff\xff\xff\xff\xff\x01", // Unknown length exceeds remaining bytes/usize.
        "\x08\x00", // Known message as varint.
        "\x09\x00\x00\x00\x00\x00\x00\x00\x00", // Known message as fixed64.
        "\x0b\x0c", // Known message as group.
        "\x0d\x00\x00\x00\x00", // Known message as fixed32.
        "\x10\x00", // Request node as varint.
        "\x19\x00\x00\x00\x00\x00\x00\x00\x00", // Boolean as fixed64.
        "\x1a\x01\x01", // Boolean as bytes.
        "\x1d\x00\x00\x00\x00", // Boolean as fixed32.
        "\x26", // Invalid unknown wire type.
        "\x23", // Unterminated unknown group.
        "\x23\x2c", // Mismatched unknown end group.
        "\x24", // Unexpected end group.
    }) |bytes| try std.testing.expectError(error.InvalidRequest, csds.decodeRequest(bytes));
}

test "CSDS codec request bounds unknown group recursion and envelope size" {
    var groups: [202]u8 = undefined;
    @memset(groups[0..101], 0x23);
    @memset(groups[101..], 0x24);
    try std.testing.expectError(error.InvalidRequest, csds.decodeRequest(&groups));
    const oversized = try allocator.alloc(u8, 1024 * 1024 + 1);
    defer allocator.free(oversized);
    @memset(oversized, 0);
    try std.testing.expectError(error.InvalidRequest, csds.decodeRequest(oversized));
}
